-- Sterling Trust Bank dataset -- run this entire script in MySQL Workbench
CREATE DATABASE IF NOT EXISTS sterling_trust_bank;
USE sterling_trust_bank;

DROP TABLE IF EXISTS Customers;
CREATE TABLE Customers (
    CustomerID VARCHAR(10),
    Name VARCHAR(100),
    Age INT,
    Gender VARCHAR(10),
    Income INT,
    TenureYears INT,
    Region VARCHAR(50)
);


DROP TABLE IF EXISTS Loans;
CREATE TABLE Loans (
    LoanID VARCHAR(10),
    CustomerID VARCHAR(10),
    LoanAmount INT,
    InterestRate DECIMAL(5,2),
    LoanStatus VARCHAR(20),
    IssueDate DATE
);


DROP TABLE IF EXISTS Transactions;
CREATE TABLE Transactions (
    TransactionID VARCHAR(10),
    CustomerID VARCHAR(10),
    TransactionDate DATE,
    Type VARCHAR(20),
    Amount DECIMAL(12,2)
);


DROP TABLE IF EXISTS ChurnLog;
CREATE TABLE ChurnLog (
    CustomerID VARCHAR(10),
    ChurnDate DATE,
    Reason VARCHAR(50)
);


-- Row count sanity check
SELECT 'Customers' AS TableName, COUNT(*) AS RowCount FROM Customers UNION ALL
SELECT 'Loans' AS TableName, COUNT(*) AS RowCount FROM Loans UNION ALL
SELECT 'Transactions' AS TableName, COUNT(*) AS RowCount FROM Transactions UNION ALL
SELECT 'ChurnLog' AS TableName, COUNT(*) AS RowCount FROM ChurnLog;